export function agruparPedidos(pedidos) {
  const grupos = {};

  pedidos.forEach((pedido) => {
    if (!grupos[pedido.estado]) {
      grupos[pedido.estado] = [];
    }
    grupos[pedido.estado].push(pedido);
  });

  return grupos;
}

export function ultimosPedidos(pedidos, cantidad) {
  const ordenados = pedidos.sort((a, b) => b.fecha - a.fecha);
  return ordenados.slice(0, cantidad);
}

export function totalPorCliente(pedidos, clienteId) {
  const delCliente = pedidos.filter((p) => p.clienteId === clienteId);
  return delCliente.map((p) => p.total).reduce((a, b) => a + b);
}

export function formatearFecha(fecha) {
  const d = new Date(fecha);
  return d.getDate() + '/' + d.getMonth() + '/' + d.getFullYear();
}
